}

/* Quiz Mode */
.quiz-container {
  max-width: 720px;
  margin: 0 auto;
}

.quiz-question-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  padding: 2rem;
  box-shadow: var(--shadow-md);
  margin-bottom: 1.5rem;
}

.quiz-options {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.quiz-option-btn {
  width: 100%;
  text-align: left;
  padding: 1rem 1.25rem;
